const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors()); // Permite que tu plataforma de Vercel se conecte sin bloqueos

// Esta es la ruta que tu archivo Metricas.jsx está buscando
app.get('/api/instagram', (req, res) => {
    // Aquí enviamos métricas simuladas de la cuenta de la facultad para el prototipo
    res.json({
        followers: 1250,
        engagement: "4.5%",
        posts: 45,
        recentViews: 850
    });
});

// Ruta de prueba para saber que el servidor está vivo
app.get('/', (req, res) => {
    res.send('¡El motor de Embajador Tomasino está en línea!');
});

const PORT = process.env.PORT || 3005;
app.listen(PORT, () => {
    console.log(`Servidor corriendo en el puerto ${PORT}`);
});